          "evidence": [
            {
              "note_id": "FCT_0062",
              "exact_quote": "Net exports decrease when domestic income rises because imports increase."
            },
            {
              "note_id": "CON_0014",
              "exact_quote": "Net exports increase when the income of the rest of the world rises because foreign demand for domestically produced goods goes up."
            },
            {
              "note_id": "CON_0015",
              "exact_quote": "When the real exchange rate rises, domestic goods become more expensive relative to foreign goods, causing exports to decline and imports to increase."
            },
            {
              "note_id": "FCT_0064",
              "exact_quote": "Net exports rise when foreign income rises."
            },
            {
              "note_id": "FCT_0065",
              "exact_quote": "A higher real exchange rate reduces net exports."
            }
          ],
